//! Static table metadata generated by `#[derive(Model)]`.

use crate::value::ColumnType;

/// SQL dialect used to render queries.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Dialect {
    /// PostgreSQL (`$1` placeholders, `"identifiers"`).
    Postgres,
    /// SQLite (`?` placeholders, `"identifiers"`).
    Sqlite,
    /// MySQL / MariaDB (`?` placeholders, `` `identifiers` ``).
    MySql,
}

impl Dialect {
    /// All dialects, in the order used by [`TableSchema::sql`].
    pub const ALL: [Dialect; 3] = [Dialect::Postgres, Dialect::Sqlite, Dialect::MySql];

    #[inline]
    pub(crate) const fn index(self) -> usize {
        match self {
            Dialect::Postgres => 0,
            Dialect::Sqlite => 1,
            Dialect::MySql => 2,
        }
    }

    /// Human readable name.
    pub const fn name(self) -> &'static str {
        match self {
            Dialect::Postgres => "PostgreSQL",
            Dialect::Sqlite => "SQLite",
            Dialect::MySql => "MySQL",
        }
    }

    /// Maximum number of bind parameters accepted in one statement.
    pub const fn max_params(self) -> usize {
        match self {
            Dialect::Postgres | Dialect::MySql => 65_535,
            Dialect::Sqlite => 32_766,
        }
    }
}

/// A foreign key constraint (`REFERENCES table(column)`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ForeignKey {
    /// Referenced table.
    pub table: &'static str,
    /// Referenced column.
    pub column: &'static str,
    /// `ON DELETE` action (`CASCADE`, `SET NULL`, ...).
    pub on_delete: Option<&'static str>,
    /// `ON UPDATE` action.
    pub on_update: Option<&'static str>,
}

/// Metadata of one column.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ColumnDef {
    /// Column name in the database.
    pub name: &'static str,
    /// Rust field name.
    pub field: &'static str,
    /// Logical type.
    pub kind: ColumnType,
    /// Accepts `NULL` (the field is an `Option<T>`).
    pub nullable: bool,
    /// Part of the primary key.
    pub primary_key: bool,
    /// Value generated by the database on insert.
    pub auto_increment: bool,
    /// `UNIQUE` constraint.
    pub unique: bool,
    /// Has a secondary index.
    pub indexed: bool,
    /// Searched with [`Column::matches`](crate::Column::matches) often: gets a
    /// full-text index where the backend has one (`#[memoire(fulltext)]`).
    pub fulltext: bool,
    /// Explicit SQL type overriding the default mapping.
    pub sql_type: Option<&'static str>,
    /// `DEFAULT` SQL expression.
    pub default: Option<&'static str>,
    /// Foreign key.
    pub references: Option<ForeignKey>,
}

/// SQL statements generated at compile time for one dialect.
///
/// Placeholders are numbered in this order:
/// * `find`, `delete`: the primary key.
/// * `insert`: every column except an auto-increment primary key.
/// * `update`: every non primary key column, then the primary key.
/// * `upsert`: every column.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct StaticSql {
    /// Qualified column list (`"t"."a", "t"."b"`).
    pub columns: &'static str,
    /// `SELECT <columns> FROM <table>`.
    pub select: &'static str,
    /// Select one row by primary key.
    pub find: &'static str,
    /// Insert one row (with `RETURNING <pk>` when the key is generated).
    pub insert: &'static str,
    /// Update one row by primary key (empty if the table only has a key).
    pub update: &'static str,
    /// Delete one row by primary key.
    pub delete: &'static str,
    /// Insert or update by primary key.
    ///
    /// On MySQL, for a table with `unique` columns besides its primary key,
    /// this is a plain `INSERT`: `ON DUPLICATE KEY UPDATE` would also fire on
    /// those columns and overwrite another row. The MySQL backend runs
    /// [`update`](Self::update) when that `INSERT` collides on the primary key
    /// (see [`TableSchema::has_secondary_unique`]).
    pub upsert: &'static str,
}

/// An index over several columns, declared on the struct with
/// `#[memoire(index(a, b))]` or `#[memoire(unique(a, b))]`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct IndexDef {
    /// Index name in the database (`idx_<table>_<a>_<b>` or `uq_<table>_<a>_<b>`).
    pub name: &'static str,
    /// Positions of the indexed columns in [`TableSchema::columns`], in order.
    pub columns: &'static [usize],
    /// No two rows may hold the same values in all these columns (rows with a
    /// `NULL` in one of them are not constrained, like in SQL).
    pub unique: bool,
}

impl IndexDef {
    /// The indexed column names joined with `", "`, as reported in
    /// [`Error::UniqueViolation`](crate::Error::UniqueViolation).
    pub fn label(&self, table: &TableSchema) -> String {
        let names: Vec<&str> = self.columns.iter().map(|&i| table.columns[i].name).collect();
        names.join(", ")
    }
}

/// Complete static description of a table.
#[derive(Debug, PartialEq, Eq)]
pub struct TableSchema {
    /// Table name.
    pub name: &'static str,
    /// Columns in declaration order.
    pub columns: &'static [ColumnDef],
    /// Index of the primary key column in `columns`.
    pub primary_key: usize,
    /// Indexes over several columns.
    pub indexes: &'static [IndexDef],
    /// Pre-rendered statements, indexed like [`Dialect::ALL`].
    pub sql: [StaticSql; 3],
}

impl TableSchema {
    /// Whether a column other than the primary key is `unique`, or the table
    /// has a unique index over several columns.
    pub fn has_secondary_unique(&self) -> bool {
        self.columns.iter().enumerate().any(|(i, c)| i != self.primary_key && c.unique)
            || self.indexes.iter().any(|ix| ix.unique)
    }

    /// The multi-column index named `name`.
    pub fn index_named(&self, name: &str) -> Option<&IndexDef> {
        self.indexes.iter().find(|ix| ix.name == name)
    }

    /// Statements for a dialect.
    #[inline]
    pub fn sql(&self, dialect: Dialect) -> &StaticSql {
        &self.sql[dialect.index()]
    }

    /// The primary key column.
    #[inline]
    pub fn pk(&self) -> &ColumnDef {
        &self.columns[self.primary_key]
    }

    /// `true` if the database generates the primary key.
    #[inline]
    pub fn auto_increment(&self) -> bool {
        self.columns[self.primary_key].auto_increment
    }

    /// Position of a column by name.
    pub fn column_index(&self, name: &str) -> Option<usize> {
        self.columns.iter().position(|c| c.name == name)
    }
}
